import React, { createContext, useState, useEffect, useContext } from 'react';
import api from '../services/api';
import { useNotification } from './NotificationContext'; // Подключаем визуальный тостер

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState(localStorage.getItem('theme') || 'light');
  const [notifications, setNotifications] = useState([]);

  // Получаем триггер вызова всплывающих уведомлений
  const { addNotification: triggerToast } = useNotification();

  useEffect(() => {
    api.get('/auth/me')
      .then(res => setUser(res.data))
      .catch(() => setUser(null))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const login = async (email, password) => {
    const res = await api.post('/auth/login', { email, password });
    setUser(res.data.user);
  };

  const register = async (data) => {
    const res = await api.post('/auth/register', data);
    setUser(res.data.user);
  };

  const logout = async () => {
    await api.post('/auth/logout');
    setUser(null);
    // Очистка персональных данных, чтобы не было утечек между пользователями
    localStorage.removeItem('purchaseReceipts');
    localStorage.removeItem('loanStatuses');
    localStorage.removeItem('tdStatuses');
    localStorage.removeItem('favorites');
    localStorage.removeItem('compareList');
  };

  const addNotification = (msg, type = 'info') => {
    // Интеллектуальное определение типа уведомления по тексту для обратной совместимости
    let determinedType = type;
    if (type === 'info') {
      const lower = msg.toLowerCase();
      if (lower.includes('одобрен') || lower.includes('успеш') || lower.includes('подтвержд')) {
        determinedType = 'success';
      } else if (lower.includes('ошибк') || lower.includes('отклон') || lower.includes('не удалос') || lower.includes('провал')) {
        determinedType = 'error';
      } else if (lower.includes('внимание') || lower.includes('заявка') || lower.includes('отправлен')) {
        determinedType = 'warning';
      }
    }

    // Сохраняем в массив истории (чтобы ничего не сломать в компонентах)
    setNotifications(prev => [...prev, { id: Date.now(), message: msg, type: determinedType }]);
    
    // Вызываем визуальный тоастер на экране
    triggerToast(msg, determinedType);
  };

  const clearNotifications = () => {
    setNotifications([]);
  };

  // Метод, который вызывается пользователем при отправке формы кредита или тест-драйва
  const sendApplicationNotification = (type) => {
    // Пишем временную метку в localStorage для мгновенного уведомления админа в соседней вкладке
    localStorage.setItem('luxury_dealer_new_app', JSON.stringify({
      type,
      timestamp: Date.now()
    }));
    localStorage.removeItem('luxury_dealer_new_app');
  };

  // Автоматический мониторинг заявок для Администратора и Менеджера
  useEffect(() => {
    if (!user || !user.role || !['admin', 'manager'].includes(user.role)) return;

    // 1. Поллинг FastAPI бэкенда на предмет новых необработанных заявок
    const fetchNewApplications = async () => {
      try {
        const res = await api.get('/api/admin/notifications/unread');
        if (res.data && Array.isArray(res.data)) {
          res.data.forEach(item => {
            addNotification(item.message, item.type || 'warning');
          });
        }
      } catch (err) {
        // Лог не спамит ошибками в консоль, пока ручка на бэкенде находится в разработке
        console.log('Система отслеживания заявок активна. Ожидание эндпоинта бэкенда...');
      }
    };

    const interval = setInterval(fetchNewApplications, 5000); // Проверка каждые 5 секунд
    fetchNewApplications();

    // 2. Слушатель для мгновенных тестов на одном компьютере (межвкладочный обмен)
    const handleStorageNotification = (e) => {
      if (e.key === 'luxury_dealer_new_app') {
        try {
          const appData = JSON.parse(e.newValue);
          if (appData) {
            const appName = appData.type === 'loan' ? 'кредит' : 'тест-драйв';
            addNotification(`Новая заявка! Клиент отправил запрос на ${appName}.`, 'warning');
          }
        } catch (err) {
          console.error(err);
        }
      }
    };
    window.addEventListener('storage', handleStorageNotification);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageNotification);
    };
  }, [user]);

  return (
    <AuthContext.Provider value={{
      user, setUser, loading, login, register, logout,
      theme, toggleTheme,
      notifications, addNotification, clearNotifications,
      sendApplicationNotification
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
